import importlib, copy, random, hashlib, hmac
from cryptography.hazmat.primitives import hashes as _hashes
_digest_cache={}
_orig_update=_hashes.Hash.update

def patched(self,data):
    obj_id=id(data)
    if obj_id not in _digest_cache:
        _digest_cache[obj_id]=hashlib.sha256(data).digest()
    return _orig_update(self,data)
_hashes.Hash.update=patched

from reference import Task
for iter in range(10):
    prob=Task().generate_problem(100,iter)
    refdigest=Task().solve(copy.deepcopy(prob))['digest']
    sol_digest=_digest_cache.get(id(prob['plaintext']))
    if not hmac.compare_digest(refdigest, sol_digest):
        print('mismatch', iter)
        break
    print('match', iter)
